_type_inference_specifiers: $ => seq(
  repeat($._declaration_modifiers),
  alias('auto', $.storage_class_specifier),
  repeat($._declaration_modifiers),
),

// http://stackoverflow.com/questions/13014947/regex-to-match-a-c-style-multiline-comment/36328890#36328890

preproc_call: $ => choice(
  seq(
    field('directive', $.preproc_directive),
    field('argument', optional($.preproc_arg)),
    token.immediate(/\r?\n/),
  ),
  // null directive (N3096 6.10.8)
  seq(field('directive', alias(/#[ \t]*/, $.preproc_directive)), token.immediate(/\r?\n/)),
),

/**
 * A directive name that is neither one of `words` nor a prefix of one, so that a
 * conditional directive outside an if-section is a syntax error instead of a preproc_call.
 *
 * @param {string[]} words
 *
 * @returns {string}
 */
function directiveName(words) {
  const prefixes = new Set(words.flatMap((w) => [...w].map((_, i) => w.slice(0, i + 1))));
  const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_';
  const node = (s) => {
    const next = [...new Set([...prefixes].filter((p) => p.length === s.length + 1 && p.startsWith(s)).map((p) => p[s.length]))];
    const other = [...(s ? chars : chars.slice(0, -1))].filter((c) => !next.includes(c)).join('');
    return '(' + ['[' + other + ']\\w*', ...next.map((c) => c + node(s + c))].join('|') + ')';
  };
  return node('');
}

module.exports.PREC = PREC;

