/**
 * The body of a group whose condition is the literal 0: the group is skipped
 * (N3096 6.10.2p6, [cpp.cond]), so only the conditional directives nested in it
 * are processed and its other lines stay text.
 *
 * @param {GrammarSymbols<string>} $
 *
 * @returns {Rule}
 */
function skippedGroup($) {
  return prec(1, seq(field('condition', alias('0', $.number_literal)), '\n', optional($.preproc_skipped)));
}

