/**
 * Lets alternative spellings (the digraphs <: :> <% %>, N3096 6.4.6p3, [lex.digraph])
 * stand for the punctuators of every rule. `spellings` maps a punctuator to its other
 * spellings: strings, or rules such as an external token for C++'s '<::' exception.
 *
 * @param {any} g
 *
 * @param {Object<string, any[]>} [spellings]
 *
 * @returns {any}
 */
function digraphs(g, spellings) {
  spellings = spellings || {'[': ['<:'], ']': [':>'], '{': ['<%'], '}': ['%>']};
  const spelt = (v) => Object.prototype.hasOwnProperty.call(spellings, v);
  const replace = (v) => {
    const strings = [v, ...spellings[v].filter((s) => typeof s === 'string')];
    const others = spellings[v].filter((s) => typeof s !== 'string');
    const token = {type: 'TOKEN', content: {type: 'CHOICE', members: strings.map((value) => ({type: 'STRING', value}))}};
    return {type: 'ALIAS', named: false, value: v, content: others.length ? {type: 'CHOICE', members: [token, ...others]} : token};
  };
  const walk = (r) => {
    if (r.type === 'TOKEN' || r.type === 'IMMEDIATE_TOKEN') return r;
    if ((r.type === 'STRING' || (r.type === 'ALIAS' && !r.named)) && spelt(r.value)) return replace(r.value);
    if (r.content) {
      const c = walk(r.content);
      if (c !== r.content) r = {...r, content: c};
    }
    if (r.members) {
      const m = r.members.map(walk);
      if (m.some((x, i) => x !== r.members[i])) r = {...r, members: m};
    }
    return r;
  };
  for (const k of Object.keys(g.grammar.rules)) g.grammar.rules[k] = walk(g.grammar.rules[k]);
  return g;
}

